def firstUniqChar(s: str) -> str:
    # 构建一个字典，记录每个字符出现的次数
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # 找出第一个出现次数为1的字符
    for char in s:
        if char_count[char] == 1:
            return char

    # 没有出现次数为1的字符，返回单空格
    return ' '

