#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* createLinkedList(int n) {
    Node* head = (Node*)malloc(sizeof(Node));
    Node* tail = head;
    for (int i = 1; i <= n; i++) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data = i;
        newNode->next = NULL;
        tail->next = newNode;
        tail = newNode;
    }
    tail->next = head->next;
    free(head);
    return tail->next;
}

int josephus(int n, int m) {
    Node* head = createLinkedList(n);
    Node* p = head;
    while (n > 1) {
        for (int i = 1; i < m; i++) {
            p = p->next;
        }
        Node* temp = p->next;
        p->next = temp->next;
        free(temp);
        n--;
    }
    int result = p->data;
    free(p);
    return result;
}

