def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        # 每次循环将最大值移到最右边
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
