double curValue = 0.0; // 计数器：累加各分支

for (Map> splits : curSplits.values()) {

double perSplitCount = 0;

for (List list : splits.values())

perSplitCount += list.size(); // 累计当前分支样本数

double perSplitValue = 0.0; // 计数器：当前分支

for (List list : splits.values()) {

