#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

#define MAX_SIZE 100

// 数据结构体定义
typedef struct Node {
    int data;
    struct Node *next;
} Node;

typedef struct Queue {
    int front;
    int rear;
    int size;
    Node *data[MAX_SIZE];
} Queue;

// 函数声明
int bfs(int graph[MAX_SIZE][MAX_SIZE], int n, int start, int end);
void enqueue(Queue *q, Node *n);
Node *dequeue(Queue *q);
Node *create_node(int data);
Queue *create_queue();
int is_empty(Queue *q);
int is_full(Queue *q);

// 主函数
int main() {
    int n, start, end;
    int graph[MAX_SIZE][MAX_SIZE];

    printf("请输入顶点数:\n");
    scanf("%d", &amp;n);

    printf("请输入邻接矩阵(0代表两点不相邻):\n");
    for (int i = 0; i &lt; n; i++) {
        for (int j = 0; j &lt; n; j++) {
            scanf("%d", &amp;graph[i][j]);
        }
    }

    printf("请输入起点和终点:\n");
    scanf("%d%d", &amp;start, &amp;end);

    int ans = bfs(graph, n, start, end);

    printf("从节点%d到节点%d的最短路程为:%d\n", start, end, ans);

    return 0;
}

// BFS算法
int bfs(int graph[MAX_SIZE][MAX_SIZE], int n, int start, int end) {
    Queue *q = create_queue();
    int *visited = (int*)calloc(n, sizeof(int));
    Node *s = create_node(start);

    visited[start] = 1;
    enqueue(q, s);

    while (!is_empty(q)) {
        Node *cur = dequeue(q);

        if (cur-&gt;data == end) { // 找到最终目标节点
            return visited[cur-&gt;data] - 1;
        }

        for (int i = 0; i &lt; n; i++) {
            if (graph[cur-&gt;data][i] &amp;&amp; !visited[i]) { // 找到与当前节点相连的未访问节点
                visited[i] = visited[cur-&gt;data] + 1;
                Node *next_node = create_node(i);
                enqueue(q, next_node);
            }
        }
    }

    return -1; // 找不到目标节点
}

// 创建一个新节点
Node *create_node(int data) {
    Node *n = (Node*)malloc(sizeof(Node));
    n-&gt;data = data;
    n-&gt;next = NULL;
    return n; 
}

// 创建一个新的队列
Queue *create_queue() {
    Queue *q = (Queue*)malloc(sizeof(Queue));
    q-&gt;front = 0;
    q-&gt;rear = -1;
    q-&gt;size = 0;
    return q;
}

// 将节点加入队列
void enqueue(Queue *q, Node *n) {
    if (is_full(q)) {
        return;
    }

    q-&gt;rear++;
    q-&gt;data[q-&gt;rear] = n;
    q-&gt;size++;
}

// 将节点从队列中移除
Node *dequeue(Queue *q) {
    if (is_empty(q)) {
        return NULL;
    }

    Node *n = q-&gt;data[q-&gt;front];
    q-&gt;front++;
    q-&gt;size--;
    return n;
}

// 判断队列是否为空
int is_empty(Queue *q) {
    return q-&gt;size == 0;
}

// 判断队列是否已满
int is_full(Queue *q) {
    return q-&gt;rear == MAX_SIZE - 1;
}

以上代码实现了一个BFS算法函数，它接收一个邻接矩阵作为图的输入，并返回从起点到终点的最短路径。函数主要包括队列数据结构和一些相关的函数，如出队、入队、判断队列是否为空或已满等。

动态规划算法是一种用于优化多阶段决策问题的算法策略。在今后的决策中，动态规划算法将为每个可能的决策点计算每一种可能的方案，并在执行每步决策时，根据可用信息和已存储的结果作出决策，从而找到一种最佳决策路径，实现全局最优解。动态规划算法通常用于解决具有重叠子问题和最优子结构性质的问题。
以下是一个经典的动态规划例子：背包问题。在背包问题中，我们有一个容量为W的背包，和一系列重量和价值不同的物品。我们需要决定如何将这些物品装入背包中，以使背包中所放物品的总价值最大，而且总重量不超过W。每个物品有一个重量和一个价值，它们都是正的。以下是使用动态规划求解背包问题的Python代码：
def knapsack(W, wt, val, n):
    dp = [[0] * (W + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(1, W + 1):
            if wt[i - 1] &gt; w:
                dp[i][w] = dp[i - 1][w]
            else:
                dp[i][w] = max(
                    dp[i - 1][w], 
                    dp[i - 1][w - wt[i - 1]] + val[i - 1]
                )

    return dp[n][W]

在此代码中，背包问题被表示为一个二维数组（i，w），其中i表示处理到物品i，w表示当前背包的容量。dp数组存储了到目前为止的最优解。在代码的第一个循环中，我们遍历每个物品并检查是否可以将该物品添加到背包中。如果物品i的重量小于等于容量w，则该物品可以被添加到背包中，其总价值为dp [i-1] [w-wt [i]] + vals [i] 。否则，我们跳过该物品并保留先前找到的最佳解。在最后一次迭代中，dp [n] [W] 包含最终的最佳解。
以上是一个示例，它说明了动态规划是如何在试图寻找全局最优解时，通过将优化问题分解为更小的子问题以及利用重叠的子问题性质来减少计算量的。

当钢条长度为i时，设最大收益为r[i]，则有以下状态转移方程：

r[i] = max(p[j] + r[i-j])，其中1<=j<=i

其中p[j]表示长度为j的钢条的价格。

以下是使用动态规划算法解决切钢条问题的C语言代码：


```c
#include <stdio.h>
#define MAX_N 1000

int p[MAX_N]; // 钢条价格数组
int r[MAX_N]; // 最大收益数组

int max(int a, int b) {
    return a > b ? a : b;
}

// 自底向上求解最大收益
int rod_cutting(int n) {
    for (int i = 1; i <= n; i++) {
        int max_val = -1;
        for (int j = 1; j <= i; j++) {
            max_val = max(max_val, p[j] + r[i-j]);
        }
        r[i] = max_val;
    }
    return r[n];
}

int main() {
    int n;
    printf("请输入钢条长度n：");
    scanf("%d", &n);
    printf("请输入长度为1~%d的钢条价格：\n", n);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &p[i]);
    }
    printf("长度为%d的钢条最大收益为：%d\n", n, rod_cutting(n));
    return 0;
}
```

这段代码中，我们先定义了一个max函数，用于比较两个数的大小并返回较大值。然后定义了两个数组p和r，分别用于存储钢条价格和最大收益。接着是求解最大收益的函数rod_cutting，该函数使用了自底向上的动态规划算法，通过两个嵌套的循环遍历所有可能的切割方案，并更新最大收益数组r。最后在主函数中读入用户输入的数据，并输出最终的结果。

