首先，聚类算法可以分为两种，一种是层次聚类，另一种是K-means聚类。本文为大家介绍K-means聚类算法的实现。

K-means聚类算法的步骤：
1. 选择K个初始的聚类中心点（可以随机选择或根据数据分布进行选择）；
2. 分别计算每个点到聚类中心点的距离（一般使用欧氏距离公式）；
3. 将每个点归为距离最近的聚类中心所在的类别；
4. 对于每个聚类，重新计算聚类中心点的位置；
5. 重复执行步骤2至4，直到聚类中心点不再改变或达到指定迭代次数。

下面是实现K-means聚类的C++代码，其中给出了详细的注释：

```c++
#include <iostream>
#include <cstdlib>
#include <ctime>
#include <cmath>
using namespace std;

// 定义一个Point结构体，用于表示数据点
struct Point {
    double x;  // 数据点x坐标
    double y;  // 数据点y坐标
    int cluster;  // 所属聚类类别
};

// 计算两点间的距离
double distance(Point p1, Point p2) {
    return sqrt(pow(p1.x - p2.x, 2) + pow(p1.y - p2.y, 2));
}

// 计算距离矩阵
void distance_matrix(Point* data, int n, double**& dist_matrix) {
    dist_matrix = new double*[n];
    for (int i=0; i<n; i++) {
        dist_matrix[i] = new double[n];
        for (int j=0; j<n; j++) {
            dist_matrix[i][j] = distance(data[i], data[j]);
        }
    }
}

// 输出距离矩阵
void print_dist_matrix(double** dist_matrix, int n) {
    for (int i=0; i<n; i++) {
        for (int j=0; j<n; j++) {
            cout << dist_matrix[i][j] << " ";
        }
        cout << endl;
    }
}

// 初始化聚类中心
void init_centers(Point* data, int n, Point* centers, int k) {
    // 随机选择k个聚类中心
    srand(time(NULL));
    for (int i=0; i<k; i++) {
        int index = rand() % n;
        centers[i].x = data[index].x;
        centers[i].y = data[index].y;
    }
}

// 将所有数据点归入距离最近的聚类中心所在的类别
void assign_clusters(Point* data, int n, Point* centers, int k) {
    for (int i=0; i<n; i++) {
        double min_dist = distance(data[i], centers[0]);
        int min_index = 0;
        for (int j=1; j<k; j++) {
            double dist = distance(data[i], centers[j]);
            if (dist < min_dist) {
                min_dist = dist;
                min_index = j;
            }
        }
        data[i].cluster = min_index;
    }
}

// 重新计算聚类中心
void recalculate_centers(Point* data, int n, Point* centers, int k) {
    for (int i=0; i<k; i++) {
        double sum_x = 0.0;
        double sum_y = 0.0;
        int count = 0;
        for (int j=0; j<n; j++) {
            if (data[j].cluster == i) {
                sum_x += data[j].x;
                sum_y += data[j].y;
                count ++;
            }
        }
        if (count > 0) {
            centers[i].x = sum_x / count;
            centers[i].y = sum_y / count;
        }
    }
}

// 判断聚类中心是否发生变化
bool centers_changed(Point* old_centers, Point* new_centers, int k) {
    for (int i=0; i<k; i++) {
        if (distance(old_centers[i], new_centers[i]) > 0.0001) {
            return true;
        }
    }
    return false;
}

// 主函数
int main() {
    const int k = 3;  // 聚类个数
    const int n = 10;  // 数据点个数
    Point data[n] = {{1, 1}, {1, 2}, {2, 1}, {4, 3}, {3, 4},
                     {4, 4}, {7, 8}, {8, 7}, {9, 7}, {7, 9}};  // 数据点集合
    Point centers[k];  // 聚类中心
    double** dist_matrix;  // 距离矩阵
    int max_iter = 100;  // 最大迭代次数
    int iter_count = 0;  // 迭代次数

    // 初始化聚类中心
    init_centers(data, n, centers, k);

    // 计算距离矩阵并输出
    distance_matrix(data, n, dist_matrix);
    cout << "Distance matrix :" << endl;
    print_dist_matrix(dist_matrix, n);
    cout << endl;

    // 迭代聚类过程
    while (iter_count < max_iter) {
        iter_count ++;
        Point old_centers[k];
        for (int i=0; i<k; i++) {
            old_centers[i] = centers[i];
        }
        // 将所有数据点归入距离最近的聚类中心所在的类别
        assign_clusters(data, n, centers, k);
        // 重新计算聚类中心
        recalculate_centers(data, n, centers, k);
        // 判断聚类中心是否发生变化，如果没变化则迭代结束
        if (!centers_changed(old_centers, centers, k)) {
            cout << "Converged after " << iter_count << " iterations." << endl;
            break;
        }
    }

    // 输出聚类结果
    cout << "Cluster result :" << endl;
    for (int i=0; i<k; i++) {
        cout << "Cluster " << i+1 << " : ";
        for (int j=0; j<n; j++) {
            if (data[j].cluster == i) {
                cout << "(" << data[j].x << ", " << data[j].y << ") ";
            }
        }
        cout << endl;
    }

    // 释放内存
    for (int i=0; i<n; i++) {
        delete[] dist_matrix[i];
    }
    delete[] dist_matrix;

    return 0;
}
```

该代码可以通过数据点的坐标计算距离矩阵，并迭代进行聚类，最终输出聚类结果。其中，数据点和聚类中心的坐标需要根据具体应用进行修改。

