import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Image;
import java.awt.Rectangle;
import java.awt.Robot;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import javax.imageio.ImageIO;
import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.Timer;

public class AutoGeneratedGIF extends JPanel {

    private static final long serialVersionUID = 1L;
    private static final int WIDTH = 500;
    private static final int HEIGHT = 500;
    private static final int FPS = 10; // 每秒帧数
    private static int t = 0;
    private static final int TOTAL_FRAMES = 60 * FPS; // 动画持续时间（60秒）
    private static final String GIF_FILENAME = "animation.gif"; // 动画文件名

    public AutoGeneratedGIF() {}

    /**
     * 重写 JPanel 中的 paint方法，绘制当前帧图像
     */
    @Override
    public void paint(Graphics g) {
        super.paint(g);
        // 绘制图形
        g.drawLine(0, 0, t * (WIDTH / TOTAL_FRAMES), HEIGHT);
        // 每帧刷新
        t++;
        if (t &gt;= TOTAL_FRAMES) {
            t = 0;
        }
    }

    /**
     * 通过 javax.swing.Timer 类创建一个定时器，初始化每帧刷新的时间间隔，启动后，每帧刷新 paint() 方法
     */
    private void startAnimation() {
        Timer timer = new Timer(1000 / FPS, new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                repaint();
            }
        });
        timer.start();
    }

    /**
     * 将 JPanel 组件绘制为 BufferedImage 类型的对象
     */
    private BufferedImage getImage() {
        BufferedImage image = new BufferedImage(getWidth(), getHeight(), BufferedImage.TYPE_INT_RGB);
        Graphics g = image.getGraphics();
        paint(g);
        g.dispose();
        return image;
    }

    /**
     * 保存 BufferedImage 类型的图片到本地文件
     */
    private void saveImage(BufferedImage image, String filename) throws IOException {
        ImageIO.write(image, "gif", new File(filename));
    }

    /**
     * 程序主入口
     */
    public static void main(String[] args) throws Exception {
        JFrame frame = new JFrame();
        frame.setPreferredSize(new Dimension(WIDTH, HEIGHT));
        frame.setResizable(false);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        AutoGeneratedGIF panel = new AutoGeneratedGIF();
        panel.setPreferredSize(new Dimension(WIDTH, HEIGHT));
        frame.setContentPane(panel);

        // 开始绘制动图
        panel.startAnimation();

        frame.pack();
        frame.setLocationRelativeTo(null);
        frame.setVisible(true);

        // 等待5秒后，保存动图
        Thread.sleep(5000);

        BufferedImage image = panel.getImage();
        panel.saveImage(image, GIF_FILENAME);
        System.out.println("GIF animation saved to file '" + GIF_FILENAME + "'.");

        System.out.println("Press any key to exit...");
        new java.util.Scanner(System.in).nextLine();

        // 释放资源
        panel.removeAll();
        panel.revalidate();
        panel.repaint();
        frame.dispose();
    }

    /**
     * 获取当前 Java 程序窗口的截图
     */
    private BufferedImage getScreenshot() throws Exception {
        Robot robot = new Robot();
        Rectangle screenRectangle = new Rectangle(WIDTH, HEIGHT);
        BufferedImage image = robot.createScreenCapture(screenRectangle);
        return image;
    }
}

