#include <iostream>
#include <vector>
#include <unordered_map>

using namespace std;

class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        unordered_map<int, int> map;
        for (int i = 0; i < nums.size(); i++) {
            int complement = target - nums[i];
            if (map.count(complement)) {
                return { map[complement], i };
            }
            map[nums[i]] = i;
        }
        return {};
    }
};

int main() {
    Solution solution;
    vector<int> nums = { 2, 7, 11, 15 };
    int target = 9;

    vector<int> result = solution.twoSum(nums, target);

    for (int i = 0; i < result.size(); i++) {
        cout << result[i] << " ";
    }

    return 0;
}

我们首先定义了一个类Solution，这个类包含了一个twoSum函数，该函数接受一个整数数组 nums 和一个整数目标值 target 作为参数，并返回一个数组，其中包含和为目标值 target 的那两个整数的下标。

我们使用unordered_map容器来存储数组元素和下标信息，遍历数组，在每个位置计算目标值与当前值的差，然后检查unordered_map中是否存在这个差，如果存在则返回这两个下标，否则将当前值和下标存入unordered_map，直到遍历完整个数组。最后，如果没有找到符合条件的两个数，则返回空数组。

我们在主函数中创建一个Solution对象并调用twoSum函数来解决问题。我们使用示例数组{ 2, 7, 11, 15 }和目标值9来测试代码，并通过循环输出两个下标的值以进行验证。

