    public static ArrayList<Child> filterChildrenByAge(ArrayList<Child> children, int age) {
        ArrayList<Child> filteredChildren = new ArrayList<>(); // 创建一个过滤后的儿童列表

        for (Child child : children) {
            if (child.getAge() < age) { // 如果当前儿童的年龄小于指定年龄，则将其添加到过滤后的列表中
                filteredChildren.add(child);
            }
        }

        return filteredChildren; // 返回过滤后的列表
    }
}

