以下是一个简单的示例区块链应用程序，用于记录和验证商品的来源和流向信息。该程序使用JavaScript编写，使用Node.js作为后端平台，并使用Express框架构建API。

```javascript
// 引入所需模块
const express = require('express');
const bodyParser = require('body-parser');
const { v4: uuidv4 } = require('uuid');
const Blockchain = require('./blockchain');

// 创建区块链实例
const blockchain = new Blockchain();

// 创建应用程序实例
const app = express();

// 使用body-parser中间件解析请求体
app.use(bodyParser.json());

// 获取整个区块链
app.get('/blockchain', (req, res) => {
  res.json(blockchain);
});

// 创建新的交易并添加到区块链
app.post('/transactions', (req, res) => {
  const { sender, recipient, amount, productInfo } = req.body;
  const transactionId = uuidv4();
  const blockIndex = blockchain.addTransactionToPendingTransactions(
    transactionId,
    sender,
    recipient,
    amount,
    productInfo
  );
  res.json({ message: `Transaction will be added to block ${blockIndex}.` });
});

// 挖掘新的区块
app.get('/mine', (req, res) => {
  const lastBlock = blockchain.getLastBlock();
  const previousBlockHash = lastBlock['hash'];
  const currentBlockData = {
    transactions: blockchain.pendingTransactions,
    index: lastBlock['index'] + 1
  };
  const nonce = blockchain.proofOfWork(previousBlockHash, currentBlockData);
  const blockHash = blockchain.hashBlock(previousBlockHash, currentBlockData, nonce);
  const newBlock = blockchain.createNewBlock(nonce, previousBlockHash, blockHash);
  res.json({ message: 'New block mined successfully.', block: newBlock });
});

// 启动服务器
app.listen(3000, () => {
  console.log('Server is running on port 3000');
});
```

